        'slack_blurb' => 'Μετατρέψτε ένα μήνυμα σε κανάλι Slack σε αίτημα και απαντήστε από τα εισερχόμενα χωρίς να φύγετε από το νήμα.',
        'entra_blurb' => 'Εισαγάγετε άτομα, ομάδες και ποιος προϊσταται σε ποιον από το Microsoft Entra ID, πριν συνδεθεί κανείς. Ρυθμίζεται στην Ταυτοποίηση.',
        'zabbix_blurb' => 'Τα προβλήματα παρακολούθησης ανοίγουν μόνα τους συμβάντα, οι επαναλήψεις προστίθενται σε αυτά και οι αποκαταστάσεις τα επιλύουν.',
        'zabbix_intro' => 'Όταν το Zabbix εντοπίζει ένα πρόβλημα - έναν δίσκο που γεμίζει, έναν διακομιστή που δεν απαντά - δημιουργεί εδώ ένα συμβάν, συσχετισμένο με τον διακομιστή αυτόν στο CMDB. Αν αναφέρει ξανά το ίδιο πρόβλημα, αυτό προστίθεται στο ίδιο αίτημα. Όταν το πρόβλημα εκλείψει, το αίτημα επιλύεται.',
        'zabbix_direction' => 'Το Zabbix καλεί το FreeITSM - το FreeITSM δεν συνδέεται ποτέ με το Zabbix, οπότε δεν χρειάζεται τη διεύθυνση του Zabbix ούτε κωδικό πρόσβασης του Zabbix. Όλα όσα χρειάζεται το Zabbix βρίσκονται παρακάτω.',
        'zabbix_not_ready' => 'Εκτελέστε πρώτα Σύστημα → Επαλήθευση βάσης δεδομένων: δημιουργεί τον πίνακα στον οποίο αυτή η ενσωμάτωση κρατά το ιστορικό συμβάντων της.',
        'zabbix_connect' => 'Σύνδεση του Zabbix',
        'zabbix_connect_body' => 'Το Zabbix στέλνει κάθε ειδοποίηση στην παρακάτω διεύθυνση μαζί με το μυστικό token. Στο Zabbix, μεταβείτε στο Alerts → Media types → Create media type, επιλέξτε Webhook, ονομάστε το FreeITSM, επικολλήστε τις παραμέτρους και το script παρακάτω και στη συνέχεια προσθέστε το σε έναν χρήστη και σε μια ενέργεια στο Alerts → Actions → Trigger actions. Επιλέξτε το «Recovery operations» στην ενέργεια, αλλιώς τα αιτήματα δεν επιλύονται ποτέ.',
        'zabbix_endpoint' => 'Η διεύθυνση του FreeITSM (δώστε την στο Zabbix)',
        'zabbix_import' => 'Πιο γρήγορα: εισαγωγή στο Zabbix',
        'zabbix_import_body' => 'Κατεβάστε το media type με όλα συμπληρωμένα - τη διεύθυνση παραπάνω, το token σας, το script και τα τρία πρότυπα μηνυμάτων - και στη συνέχεια, στο Zabbix, μεταβείτε στο Alerts → Media types → Import και επιλέξτε το αρχείο. Μετά, αναθέστε το σε έναν χρήστη και προσθέστε μια ενέργεια (βήμα 4 του οδηγού).',
        'zabbix_import_download' => 'Λήψη για εισαγωγή στο Zabbix',
