        'zabbix_token_make' => 'Δημιουργία token',
        'zabbix_token_rotate' => 'Νέο token',
        'zabbix_rotate_confirm' => 'Θέλετε να δημιουργηθεί νέο token; Το παλιό παύει να λειτουργεί αμέσως, οπότε το Zabbix θα αποτυγχάνει μέχρι να επικολλήσετε το νέο στο media type του.',
        'zabbix_params' => 'Παράμετροι του media type',
        'zabbix_params_hint' => 'Διαγράψτε τις παραμέτρους που συμπληρώνει το Zabbix για ένα νέο webhook (URL, HTTPProxy, To, Subject, Message) - ανήκουν στο δικό του παράδειγμα script, όχι σε αυτό. Στη συνέχεια προσθέστε κάθε γραμμή εδώ ως παράμετρο: το όνομα αριστερά, την τιμή δεξιά. Το http_proxy παραμένει κενό, εκτός αν ο διακομιστής Zabbix μπορεί να φτάσει το FreeITSM μόνο μέσω proxy. Οι τιμές σε αγκύλες είναι μακροεντολές του Zabbix - αφήστε τις όπως είναι. Η γραμμή url δίνει σε κάθε αίτημα έναν σύνδεσμο προς το πρόβλημα στο Zabbix· χρειάζεται να έχει οριστεί η μακροεντολή {$ZABBIX.URL} με τη διεύθυνση web του Zabbix (Zabbix: Administration → Macros). Χωρίς αυτήν, τα αιτήματα απλώς δεν έχουν σύνδεσμο.',
