        'zabbix_company_hint' => 'Χρησιμοποιείται όταν ο διακομιστής δεν υπάρχει στο CMDB ή το στοιχείο του στο CMDB δεν έχει εταιρεία. Ένας διακομιστής που έχει, πηγαίνει στη δική του εταιρεία.',
