        'zabbix_resolve_hint' => 'Ένα μήνυμα «αποκατάστασης» προστίθεται πάντα στο αίτημα. Αυτό καθορίζει αν αλλάζει και η κατάστασή του.',
        'zabbix_link_cmdb' => 'Συσχέτιση του στοιχείου CMDB με το ίδιο όνομα με τον host του Zabbix',
        'zabbix_link_cmdb_hint' => 'Πρώτα το πλήρες όνομα και μετά το σύντομο (web01 για το web01.example.com). Αν δύο εταιρείες έχουν και οι δύο αντιστοίχιση, δεν συσχετίζεται κανένα.',
