        'zabbix_act_error' => 'Απέτυχε',
        'zabbix_recovery' => 'αποκατάσταση',
        'zabbix_test' => 'Δοκιμάστε το',
        'zabbix_test_body' => 'Στέλνει ένα δοκιμαστικό πρόβλημα μέσω της ενσωμάτωσης, ακριβώς όπως χειρίζεται μια πραγματική ειδοποίηση από το Zabbix: δημιουργείται ένα συμβάν με τις ρυθμίσεις σας και στη συνέχεια μπορείτε να στείλετε την αποκατάστασή του για να το δείτε να επιλύεται. Το δοκιμαστικό συμβάν παραμένει, με τίτλο που δείχνει ότι είναι δοκιμή, ώστε να δείτε πώς μοιάζει ένα πραγματικό - κλείστε το όπως κάθε άλλο αίτημα.',
        'zabbix_test_limit' => 'Αυτό δοκιμάζει το δικό του μισό του FreeITSM. Το αν ο διακομιστής Zabbix μπορεί να φτάσει το FreeITSM είναι το άλλο μισό: δοκιμάστε το με το κουμπί Test στο media type στο Zabbix.',
        'zabbix_test_send' => 'Αποστολή δοκιμαστικής ειδοποίησης',
        'zabbix_test_recover' => 'Αποστολή αποκατάστασης',
        'zabbix_test_raised' => 'Δημιουργήθηκε το δοκιμαστικό συμβάν {ticket}.',
        'zabbix_test_resolved' => 'Λήφθηκε η αποκατάσταση - το {ticket} επιλύθηκε.',
        'zabbix_test_failed' => 'Η δοκιμή απέτυχε: {error}',
        'zabbix_test_trigger' => 'Δοκιμαστική ειδοποίηση από το FreeITSM',
        'zabbix_test_message' => 'Αυτό είναι ένα δοκιμαστικό μήνυμα από το Σύστημα → Ενσωματώσεις → Zabbix. Δεν υπάρχει κανένα πρόβλημα.',
        'msteams_blurb' => 'Ειδοποιήσεις του service desk ως κάρτες στα κανάλια σας του Teams - επείγοντα αιτήματα, παραβιάσεις SLA, αιτήματα για κάθε ομάδα - με κουμπί που οδηγεί κατευθείαν στο αίτημα.',
        'msteams_intro' => 'Δημοσιεύστε ειδοποιήσεις του service desk σε κανάλια του Microsoft Teams ως κάρτες, καθεμία με κουμπί Άνοιγμα στο FreeITSM. Επιλέξτε για τι θέλετε να ενημερώνεται κάθε κανάλι: επείγοντα αιτήματα, προειδοποιήσεις και παραβιάσεις SLA, τα αιτήματα των ομάδων του, συμβάντα της σελίδας κατάστασης, εγκρίσεις που αναμένουν.',
        'msteams_not_ready' => 'Εκτελέστε πρώτα Σύστημα → Επαλήθευση βάσης δεδομένων: δημιουργεί τους πίνακες στους οποίους κρατούνται αυτές οι ειδοποιήσεις.',
        'msteams_bot_h' => 'Το bot συνομιλίας του Teams',
        'msteams_bot_body' => 'Αυτή η σελίδα μόνο δημοσιεύει ειδοποιήσεις. Για να συνομιλούν οι χρήστες με το service desk στο Teams - κάθε συνομιλία ένα αίτημα - ρυθμίστε το bot του Teams στο Αιτήματα → Ρυθμίσεις → Μηνύματα.',
        'msteams_bot_count' => 'Έχουν ρυθμιστεί {n} κανάλι(α) bot του Teams.',
        'msteams_bot_link' => 'Άνοιγμα ρυθμίσεων μηνυμάτων',
        'msteams_how_h' => 'Λήψη της διεύθυνσης webhook ενός καναλιού',
        'msteams_how_body' => 'Στο Teams, ανοίξτε το κανάλι, κάντε κλικ στο … δίπλα στο όνομά του και στη συνέχεια στο Workflows. Επιλέξτε «Post to a channel when a webhook request is received», ακολουθήστε τα βήματα και αντιγράψτε τη διεύθυνση που σας δίνει στο τέλος. Επικολλήστε την σε ένα κανάλι παρακάτω. Η διεύθυνση λειτουργεί σαν κωδικός πρόσβασης: όποιος την έχει μπορεί να δημοσιεύσει στο κανάλι, γι\' αυτό αποθηκεύεται κρυπτογραφημένη και δεν εμφανίζεται ποτέ ξανά.',
        'msteams_channels_h' => 'Κανάλια',
        'msteams_channels_none' => 'Κανένα κανάλι ακόμη. Προσθέστε ένα για κάθε κανάλι του Teams που πρέπει να λαμβάνει ειδοποιήσεις.',
        'msteams_add' => 'Προσθήκη',
        'msteams_name' => 'Όνομα καναλιού',
        'msteams_name_ph' => 'π.χ. Ειδοποιήσεις service desk',
        'msteams_url' => 'Διεύθυνση webhook',
        'msteams_url_saved' => 'Αποθηκεύτηκε - επικολλήστε νέα διεύθυνση για να την αντικαταστήσετε',
        'msteams_url_new' => 'https://… από τα Teams Workflows',
        'msteams_url_clear' => 'Αφαίρεση της αποθηκευμένης διεύθυνσης (σταματά κάθε ειδοποίηση προς αυτό το κανάλι)',
