        'msteams_no_teams' => 'Καμία ομάδα ακόμη.',
        'msteams_workflows_note' => 'Κάθε ειδοποίηση που επιλέγετε είναι μια ροή εργασιών με όνομα «Teams: …» στη σελίδα Ροές εργασιών, όπου βρίσκονται το ιστορικό και οι παραδόσεις της. Αλλάξτε την από εδώ: μια αλλαγή που γίνεται εκεί αντικαθίσταται την επόμενη φορά που θα αποθηκευτεί αυτό το κανάλι.',
        'msteams_on' => '{n} ειδοποίηση(εις) ενεργή(ές)',
        'msteams_saved' => 'Αποθηκεύτηκε - {n} ειδοποίηση(εις) ενεργή(ές).',
        'msteams_test' => 'Δοκιμή',
        'msteams_test_sent' => 'Στάλθηκε ({detail}) - ελέγξτε το κανάλι στο Teams.',
        'msteams_test_failed' => 'Το Teams δεν το αποδέχθηκε: {detail}',
        'msteams_delete_confirm' => 'Θέλετε να διαγράψετε αυτό το κανάλι και τις ροές εργασιών που δημιούργησε; Το ιστορικό τους παραμένει στη σελίδα Ροές εργασιών.',
        'msteams_needs_name' => 'Δώστε όνομα στο κανάλι.',
        'threecx_blurb' => 'Δείτε ποιος σας καλεί πριν απαντήσετε, κρατήστε κάθε κλήση στο αίτημα του καλούντος και καλέστε έναν αριθμό με ένα κλικ.',
        'threecx_intro' => 'Όταν χτυπά μια κλήση, το 3CX ρωτά το FreeITSM σε ποιον ανήκει ο αριθμός και εμφανίζει το όνομα του καλούντος - και ανοίγει το αίτημά του για τον τεχνικό. Όταν τελειώσει η κλήση, καταγράφεται σε αυτό το αίτημα, γραμμένη από τον τεχνικό που την απάντησε. Οι αριθμοί τηλεφώνου σε αιτήματα και άτομα μπορούν επίσης να κληθούν μέσω του 3CX.',
        'threecx_direction' => 'Το 3CX καλεί το FreeITSM - το FreeITSM δεν συνδέεται ποτέ με το 3CX, οπότε δεν χρειάζεται τη διεύθυνση του τηλεφωνικού σας συστήματος ούτε κωδικό πρόσβασης του 3CX. Όλα όσα χρειάζεται το 3CX βρίσκονται στο παρακάτω πρότυπο.',
        'threecx_not_ready' => 'Εκτελέστε πρώτα Σύστημα → Επαλήθευση βάσης δεδομένων: δημιουργεί τον πίνακα στον οποίο αυτή η ενσωμάτωση κρατά το ιστορικό κλήσεών της.',
        'threecx_connect' => 'Σύνδεση του 3CX',
        'threecx_connect_body' => 'Το 3CX συσχετίζεται με το FreeITSM μέσω ενός προτύπου CRM. Δημιουργήστε ένα token, κατεβάστε το πρότυπο και ανεβάστε το στην Κονσόλα διαχείρισης του 3CX στο Integrations → CRM. Το 3CX πρέπει να μπορεί να φτάσει την παρακάτω διεύθυνση.',
        'threecx_endpoint' => 'Η διεύθυνση του FreeITSM, όπως θα τη φτάνει το 3CX',
        'threecx_reach_hint' => 'Ξεκινά ως το δημόσιο βασικό URL σας. Το 3CX βρίσκεται συχνά στο cloud, οπότε πρέπει να είναι διεύθυνση προσβάσιμη από το διαδίκτυο. Αλλάξτε την εδώ και η λήψη ακολουθεί.',
        'threecx_token' => 'Token',
        'threecx_token_none' => 'Δεν υπάρχει ακόμη token - δημιουργήστε ένα για να ενεργοποιήσετε την ενσωμάτωση.',
        'threecx_token_make' => 'Δημιουργία',
        'threecx_token_rotate' => 'Αντικατάσταση',
        'threecx_rotate_confirm' => 'Θέλετε να δημιουργηθεί νέο token; Το 3CX παύει να φτάνει το FreeITSM μέχρι να ανεβάσετε ξανά το πρότυπο (ή να επικολλήσετε σε αυτό το νέο token).',
        'threecx_copy' => 'Αντιγραφή',
        'threecx_copied' => 'Αντιγράφηκε.',
        'threecx_download' => 'Λήψη',
        'threecx_download_body' => 'Το πρότυπο, έτοιμο για ανέβασμα: η διεύθυνση, αυτό το token, η αναζήτηση καλούντος και η αναφορά κλήσης. Περιέχει το token, γι\' αυτό κρατήστε το αρχείο για τον εαυτό σας.',
        'threecx_download_needs_token' => 'Δημιουργήστε πρώτα ένα token - το πρότυπο το περιέχει.',
        'threecx_calls_h' => 'Κλήσεις σε αιτήματα',
        'threecx_rule' => 'Σε ποιο αίτημα καταχωρείται μια κλήση',
        'threecx_rule_latest' => 'Το πιο πρόσφατα ενημερωμένο ανοιχτό αίτημα του καλούντος',
        'threecx_rule_only_one' => 'Μόνο όταν ο καλών έχει ακριβώς ένα ανοιχτό αίτημα',
        'threecx_rule_log_only' => 'Κανένα - οι κλήσεις μόνο εμφανίζονται στη λίστα παρακάτω',
        'threecx_rule_hint' => 'Το αίτημα που ανοίγει το 3CX για τον τεχνικό όταν χτυπά η κλήση ακολουθεί την ίδια επιλογή.',
        'threecx_create' => 'Άνοιγμα νέου αιτήματος για κλήση από κάποιον χωρίς ανοιχτό αίτημα',
        'threecx_create_unknown' => 'Και για αριθμούς που κανείς στο FreeITSM δεν έχει',
        'threecx_create_hint' => 'Μόνο για εισερχόμενες κλήσεις (απαντημένες ή αναπάντητες). Ανατίθεται στον τεχνικό που απάντησε την κλήση. Ένας άγνωστος καλών καταχωρείται ως «Caller» με τον αριθμό του, έτοιμος να συσχετιστεί με το σωστό άτομο.',
        'threecx_fallback' => 'Καταγραφή σημειώσεων ως, όταν ο χρήστης του 3CX δεν είναι τεχνικός',
        'threecx_fallback_hint' => 'Μια σημείωση γράφεται από τον τεχνικό του οποίου το email ταιριάζει με τον χρήστη του 3CX που απάντησε την κλήση. Όταν δεν ταιριάζει κανένας - μια ρεσεψιόν, ένα κοινόχρηστο τηλέφωνο - γράφεται από αυτόν τον τεχνικό, με αναφορά στο ποιος την απάντησε. Αν δεν έχει επιλεγεί κανείς, αυτές οι κλήσεις μόνο εμφανίζονται στη λίστα παρακάτω.',
        'threecx_nobody' => 'Κανείς',
        'threecx_company' => 'Εταιρεία για αιτήματα από άγνωστους αριθμούς',
        'threecx_company_hint' => 'Το αίτημα ενός γνωστού καλούντος πηγαίνει στη δική του εταιρεία.',
        'threecx_team' => 'Ομάδα για νέα αιτήματα',
        'threecx_origin' => 'Προέλευση για νέα αιτήματα',
        'threecx_none' => 'Καμία',
        'threecx_dial_h' => 'Κλήση με ένα κλικ',
        'threecx_dial_body' => 'Οι αριθμοί τηλεφώνου σε αιτήματα, στο Αιτήματα → Χρήστες και στα Άτομα αποκτούν κουμπί Κλήση που καλεί μέσω του τηλεφώνου σας. Ανοίγει στον δικό του υπολογιστή του τεχνικού, όπου είναι ήδη συνδεδεμένος στο 3CX, οπότε το FreeITSM δεν χρειάζεται ποτέ το εσωτερικό του.',
        'threecx_dial' => 'Διεύθυνση κλήσης',
        'threecx_dial_hint' => 'Τοποθετήστε το {number} εκεί όπου μπαίνει ο αριθμός. Για τον web client του 3CX: https://your-pbx.3cx.com/webclient/#/call?phone={number}. Για την εφαρμογή επιφάνειας εργασίας του 3CX (ή οποιοδήποτε softphone): tel:{number}. Αφήστε το κενό για να απενεργοποιήσετε τα κουμπιά Κλήση.',
        'threecx_saved' => 'Αποθηκεύτηκε.',
        'threecx_try' => 'Δοκιμή κλήσης',
        'threecx_try_body' => 'Δείτε τι θα έκανε μια κλήση με αυτές τις ρυθμίσεις - ποιος είναι ο καλών, σε ποιο αίτημα θα καταχωρούνταν και από ποιον θα γραφόταν η σημείωση. Δεν γράφεται τίποτα: είναι η ίδια απόφαση που παίρνει μια πραγματική κλήση, απλώς περιγραφόμενη.',
        'threecx_try_number' => 'Αριθμός τηλεφώνου',
        'threecx_try_type' => 'Κλήση',
        'threecx_try_agent' => 'Απαντήθηκε από (email του χρήστη 3CX)',
        'threecx_try_go' => 'Δοκιμή',
        'threecx_try_caller' => 'Καλών: {name}.',
        'threecx_try_nobody' => 'Καλών: κανείς στο FreeITSM δεν έχει αυτόν τον αριθμό - το 3CX εμφανίζει άγνωστο καλούντα.',
        'threecx_try_several' => 'Καλών: {n} άτομα έχουν αυτόν τον αριθμό - το 3CX εμφανίζει άγνωστο καλούντα αντί να μαντέψει.',
        'threecx_try_noted' => 'Θα καταγραφόταν στο {ticket}, γραμμένη από {author}.',
