        'threecx_act_logged' => 'Μόνο στη λίστα',
        'threecx_act_error' => 'Απέτυχε',
        'configured' => 'Ρυθμισμένη',
        'not_configured' => 'Δεν έχει ρυθμιστεί',
        'tika_blurb' => 'Διαβάστε το κείμενο μέσα σε PDF, παλαιότερα αρχεία Office και σαρωμένα έγγραφα ώστε να είναι δυνατή η αναζήτησή τους.',
        'tika_intro' => 'Κατευθύνει το FreeITSM σε μια υπηρεσία ανάγνωσης εγγράφων. Τα αρχεία Word, Excel, PowerPoint και απλού κειμένου αναζητούνται ήδη χωρίς αυτήν· το Tika προσθέτει τις μορφές που το FreeITSM δεν μπορεί να διαβάσει μόνο του.',
        'tika_security_title' => 'Κρατήστε το εκτός δικτύου',
        'tika_security_body' => 'Το Tika δεν έχει κωδικό πρόσβασης ούτε οποιαδήποτε ταυτοποίηση: ό,τι μπορεί να το φτάσει θα διαβάσει όποιο αρχείο του σταλεί. Εκτελέστε το έτσι ώστε μόνο αυτός ο διακομιστής να μπορεί να επικοινωνεί μαζί του — δεσμευμένο στο 127.0.0.1 ή σε ιδιωτικό δίκτυο containers — και ποτέ μην εκθέτετε τη θύρα του στο διαδίκτυο.',
        'tika_connection' => 'Σύνδεση',
        'tika_url_label' => 'Διεύθυνση',
        'tika_url_hint' => 'Για παράδειγμα http://127.0.0.1:9998. Αφήστε το κενό για να απενεργοποιήσετε την ανάγνωση εγγράφων· τα PDF θα εμφανίζονται απλώς ως μη αναγνώσιμα.',
        'tika_timeout_label' => 'Χρονικό όριο (δευτερόλεπτα)',
        'tika_timeout_hint' => 'Πόση ώρα να περιμένει για ένα έγγραφο. Οι σαρωμένες σελίδες χρειάζονται πολύ περισσότερο από το απλό κείμενο.',
