        'slack_signing_secret' => 'Signing secret',
        'slack_signing_secret_hint' => 'Από την εφαρμογή Slack, στο Basic Information. Έτσι το FreeITSM διαπιστώνει ότι ένα μήνυμα προήλθε πράγματι από το Slack, οπότε δεν γίνεται αποδεκτό τίποτα μέχρι να οριστεί.',
