        'slack_delete_confirm' => 'Θέλετε να διαγράψετε τον χώρο εργασίας Slack «{name}»; Τα αιτήματα που έχουν ήδη δημιουργηθεί από αυτόν διατηρούν το ιστορικό τους· μόνο τα νέα μηνύματα σταματούν να φτάνουν.',
        'slack_diag_title' => 'Έλεγχος υγείας του Slack',
        'slack_diag_desc' => 'Ελέγχει ό,τι μπορεί να είναι αθόρυβα λάθος — όχι μόνο αν λειτουργεί το token. Κάθε αποτέλεσμα λέει τι να κάνετε γι\' αυτό.',
        'slack_diag_running' => 'Έλεγχος σε εξέλιξη — επικοινωνεί με το Slack και με τη δική σας δημόσια διεύθυνση, οπότε δώστε του λίγα δευτερόλεπτα…',
        'slack_diag_rerun' => 'Νέα εκτέλεση',
        'slack_diag_all_ok' => 'Όλα είναι εντάξει. Τα μηνύματα που δημοσιεύονται στο παρακολουθούμενο κανάλι Slack θα γίνονται αιτήματα και οι απαντήσεις θα επιστρέφουν στο νήμα.',
        'slack_diag_some_warn' => 'Λειτουργεί, με κάτι που αξίζει να γνωρίζετε. Τίποτα παρακάτω δεν εμποδίζει την άφιξη αιτημάτων, αλλά αξίζει να το διαβάσετε.',
        'slack_diag_some_fail' => 'Κάτι δεν πάει καλά και τα μηνύματα δεν θα φτάνουν. Οι έλεγχοι που απέτυχαν παρακάτω λένε τι να κάνετε.',
