        'slack_scopes_desc' => 'Ο διαχειριστής του Slack θα δει αυτή τη λίστα όταν εγκρίνει την εφαρμογή. Τίποτα από αυτά δεν της επιτρέπει να δημιουργεί κανάλια, να προσκαλεί άτομα ή να δημοσιεύει σε σημεία όπου δεν έχει προσκληθεί.',
        'slack_step1' => 'Στο Slack, μεταβείτε στο <strong>api.slack.com/apps</strong> και επιλέξτε <strong>Create New App → From a manifest</strong>. Διαλέξτε το workspace στο οποίο θέλετε να λειτουργεί η υπηρεσία υποστήριξης.',
        'slack_step2' => 'Επικολλήστε αυτό το manifest. Ορίζει το όνομα, τα δικαιώματα και τη διεύθυνση στην οποία το Slack στέλνει τα μηνύματα, ώστε να μη χρειάζεται να επιλέξετε τίποτα με το χέρι.',
        'slack_step3' => 'Πατήστε <strong>Install to Workspace</strong> και εγκρίνετε την εφαρμογή. Στη συνέχεια αντιγράψτε το <strong>Bot User OAuth Token</strong> και το <strong>Signing Secret</strong> στη φόρμα επεξεργασίας εδώ — το Slack δεν θα εμφανίσει ξανά το token. <strong>Αν το Slack εμφανίσει ένα κίτρινο banner &ldquo;Reinstall to Workspace&rdquo;, πατήστε το πρώτα</strong> — διαφορετικά το token δεν έχει τα περισσότερα από τα δικαιώματά του και τα αιτήματα φτάνουν χωρίς το όνομα του αποστολέα.',
        'slack_step4' => 'Ελέγξτε ότι το request URL παρακάτω ταυτίζεται με αυτό που εμφανίζει το Slack στο <strong>Event Subscriptions</strong>. Το Slack το επαληθεύει τη στιγμή που αποθηκεύετε την εφαρμογή, επομένως ο διακομιστής αυτός πρέπει να είναι προσβάσιμος από το διαδίκτυο.',
        'slack_step5' => 'Στο Slack, προσκαλέστε την εφαρμογή στο κανάλι που θέλετε να παρακολουθεί: <strong>/invite @YourApp</strong>. Δεν μπορεί να διαβάσει ένα κανάλι στο οποίο δεν συμμετέχει.',
