        'inbound_heading' => 'Αλλαγές που γίνονται στο ημερολόγιο',
        'inbound_desc' => 'Μετακινήστε ένα από αυτά τα ραντεβού στο Outlook και το αίτημα ακολουθεί. Για αυτό πρέπει να εκτελείται η εργασία <code>cron/calendar_sync_pull.php</code> &mdash; κάθε 5 λεπτά είναι λογικό. Χωρίς αυτήν ο συγχρονισμός είναι μονόδρομος, όπως ακριβώς λειτουργεί σήμερα.',
        'accept_deletes' => 'Η διαγραφή του ραντεβού αναιρεί τον προγραμματισμό του αιτήματος',
        'notify_url' => 'Διεύθυνση ειδοποίησης (προαιρετικό)',
        'notify_url_note' => 'Αφήστε το κενό για να βασίζεστε μόνο στον προγραμματισμένο έλεγχο, που είναι απολύτως επαρκής &mdash; οι αλλαγές τότε φτάνουν μέσα σε λίγα λεπτά. Αν το συμπληρώσετε, η Microsoft θα ενημερώνει το FreeITSM τη στιγμή που αλλάζει κάτι, ώστε να φτάνει σε δευτερόλεπτα. Πρέπει να είναι <strong>διεύθυνση HTTPS που η Microsoft μπορεί να προσεγγίσει από το internet</strong>, και να τελειώνει σε <code>/api/calendar/graph_notify.php</code>. Η προγραμματισμένη εργασία χρειάζεται σε κάθε περίπτωση: ανανεώνει τις συνδρομές και πιάνει ό,τι θα χανόταν από μια ειδοποίηση που δεν έφτασε.',
