        'health_stale_note' => 'Οι αλλαγές που γίνονται στο Outlook φτάνουν όταν εκτελείται η προγραμματισμένη εργασία, οπότε αυτό συνήθως σημαίνει ότι έχει σταματήσει &mdash; ελέγξτε ότι το <code>cron/calendar_sync_pull.php</code> εκτελείται ακόμη σύμφωνα με το πρόγραμμά του. Είναι επίσης αυτό που ανανεώνει τις συνδρομές, οπότε οι ειδοποιήσεις σταματούν λίγες ημέρες μετά από αυτό. Αν το εκτελείτε σκόπιμα πιο αραιά από κάθε μισή ώρα, αυτό είναι αναμενόμενο.',
