        'sub_lapsed' => 'Η συνδρομή έληξε',
        'accept_deletes_note' => 'Ανενεργό από προεπιλογή. Όταν είναι ενεργό, ένας τεχνικός που διαγράφει ένα από αυτά στο κινητό του βρίσκει το αίτημα ήδη χωρίς προγραμματισμό όταν κάθεται στο γραφείο &mdash; κάτι που συχνά είναι και το ζητούμενο. Κάθε τέτοια αλλαγή καταγράφεται στο ιστορικό του αιτήματος, και ένας ασυνήθιστα μεγάλος αριθμός διαγραφών ταυτόχρονα απορρίπτεται αντί να εκτελεστεί, καθώς είναι πιο πιθανό να πρόκειται για σφάλμα παρά για εντολή. Όταν είναι ανενεργό, ένα διαγραμμένο ραντεβού απλώς εμφανίζεται ξανά την επόμενη φορά που αλλάζει το αίτημα.',
