        'lockout_desc' => 'Κλειδώστε τους λογαριασμούς μετά από επαναλαμβανόμενες αποτυχημένες προσπάθειες σύνδεσης, για να αποτρέψετε επιθέσεις ωμής βίας. Ορίστε τον μέγιστο αριθμό προσπαθειών σε 0 για να απενεργοποιήσετε το κλείδωμα.',
        'max_attempts' => 'Μέγιστες αποτυχημένες προσπάθειες',
        'max_attempts_hint' => 'Αριθμός λανθασμένων κωδικών πριν κλειδωθεί ο λογαριασμός',
        'lockout_duration' => 'Διάρκεια κλειδώματος',
        'lockout_duration_hint' => 'Για πόσο διάστημα ο λογαριασμός παραμένει κλειδωμένος (ο μετρητής μηδενίζεται μετά το ξεκλείδωμα)',
        'ipban_heading' => 'Αποκλεισμός IP',
        'ipban_desc' => 'Αποκλείει αυτόματα διευθύνσεις IP που επιχειρούν επανειλημμένα να συνδεθούν σε ανύπαρκτους ή κλειδωμένους λογαριασμούς. Κάθε αποκλεισμός διαρκεί 24 ώρες. Μετά από κάθε αποκλεισμό το όριο μειώνεται κατά 1 (έως το ελάχιστο), ώστε οι επαναλαμβανόμενοι παραβάτες να δυσκολεύονται περισσότερο. Ορίστε τον μέγιστο αριθμό προσπαθειών σε 0 για απενεργοποίηση.',
        'first_ban' => 'Όριο πρώτου αποκλεισμού',
        'first_ban_hint' => 'Αποτυχημένες προσπάθειες πριν αποκλειστεί η IP για πρώτη φορά',
        'min_threshold' => 'Ελάχιστο όριο',
        'min_threshold_hint' => 'Το όριο σταματά να μειώνεται όταν φτάσει σε αυτή την τιμή',
        'ipban_example_strong' => 'Παράδειγμα:',
        'ipban_example_text' => 'Με μέγιστο 5 και ελάχιστο 2, ο πρώτος αποκλεισμός ενεργοποιείται μετά από 5 αποτυχημένες προσπάθειες, ο δεύτερος μετά από 4, μετά 3 και μετά 2. Παραμένει στο 2 για κάθε επόμενο αποκλεισμό. Μετρούν μόνο οι προσπάθειες σε ανύπαρκτα ονόματα χρήστη ή σε ήδη κλειδωμένους λογαριασμούς.',
        'attachments_heading' => 'Συνημμένα',
        'attachments_desc' => 'Το FreeITSM δέχεται μόνο τους τύπους συνημμένων που αναγνωρίζει. Οτιδήποτε άλλο - ένα πρόγραμμα, ένα script, μια ιστοσελίδα - δεν αποθηκεύεται ποτέ με το δικό του όνομα, ώστε να μην μπορεί να εκτελεστεί.',
        'rejected_behaviour' => 'Όταν ένας τύπος αρχείου δεν γίνεται δεκτός',
        'rejected_behaviour_hint' => 'Ισχύει για το email, την πύλη και τα κανάλια συνομιλίας.',
        'rejected_store' => 'Διατήρηση, μόνο λήψη',
        'rejected_drop' => 'Να μη διατηρείται',
        'allowed_extensions' => 'Αποδεκτοί τύποι αρχείων',
        'allowed_extensions_hint' => 'Αφήστε το κενό για να γίνονται δεκτά όλα όσα το FreeITSM θεωρεί ασφαλή, συμπεριλαμβανομένων νέων τύπων που προστίθενται σε μελλοντικές ενημερώσεις. Για να δέχεστε λιγότερους, καταγράψτε μόνο τις επεκτάσεις που θέλετε, χωρισμένες με κόμματα.',
        'allowed_extensions_ph' => 'π.χ. pdf, docx, xlsx, png, jpg',
        'allowed_extensions_note' => 'Μπορείτε μόνο να περιορίσετε αυτή τη λίστα. Μια επέκταση που το FreeITSM δεν θεωρεί ήδη ασφαλή αγνοείται, ώστε τίποτα από όσα πληκτρολογήσετε εδώ να μην κάνει αποδεκτό ένα πρόγραμμα ή ένα script.',
        'rejected_note' => 'Και στις δύο περιπτώσεις το αίτημα αναφέρει τι συνέβη και γιατί, ώστε κανείς να μη χρειάζεται να αναρωτιέται πού πήγε το αρχείο του.',
        'max_attachment' => 'Μεγαλύτερο συνημμένο',
        'max_attachment_hint' => 'Κανένα συνημμένο δεν μπορεί να είναι μεγαλύτερο από αυτό - σε email, πύλη, κανάλια συνομιλίας, απαντήσεις και συνημμένα έγγραφα. 10 MB εκτός αν το αλλάξετε.',
        'max_total' => 'Μεγαλύτερο email',
        'max_total_hint' => 'Όλα τα συνημμένα ενός εισερχόμενου email μαζί. Το 0 σημαίνει κανένα όριο πέρα από το παραπάνω.',
        'php_limits' => 'Η PHP σε αυτόν τον διακομιστή δέχεται μεταφορτώσεις από το πρόγραμμα περιήγησης έως {upload} ανά αρχείο και {post} ανά αίτηση (upload_max_filesize και post_max_size στο php.ini) και διαθέτει {memory} μνήμης. Ένα αρχείο που αρνείται η PHP δεν φτάνει ποτέ στο FreeITSM, επομένως ένα όριο πάνω από αυτά βοηθά μόνο το email. Ένας διακομιστής ιστού ή proxy μπροστά (nginx client_max_body_size, IIS maxAllowedContentLength) μπορεί να ορίζει δικό του χαμηλότερο όριο.',
        'php_limits_warn' => 'Το μεγαλύτερο συνημμένο είναι υψηλότερο από όσο δέχεται η PHP από ένα πρόγραμμα περιήγησης: αυξήστε και τα upload_max_filesize και post_max_size στο php.ini, αλλιώς τα αρχεία που μεταφορτώνονται μέσω του FreeITSM θα απορρίπτονται πριν φτάσουν.',
        'php_unlimited' => 'χωρίς όριο',
        'oversize_signpost' => 'Τι συμβαίνει με ένα εισερχόμενο email πάνω από αυτά τα όρια - απόρριψη ή διατήρηση χωρίς τα συνημμένα που είναι πολύ μεγάλα, και ποιος ενημερώνεται - ορίζεται στο {link}. Κάθε γραμματοκιβώτιο μπορεί επίσης να ορίσει εκεί δικά του όρια.',
        'oversize_signpost_link' => 'Αιτήματα -> Ρυθμίσεις -> Γραμματοκιβώτια',
