    'sso' => [
        'title' => 'Έλεγχος ταυτότητας',
        'subtitle' => 'Επιτρέψτε στους χρήστες να συνδέονται μέσω εξωτερικού παρόχου ταυτότητας (OpenID Connect), όπως Keycloak, Microsoft Entra, Okta ή Google, ή μέσω του LDAP / Active Directory σας — παράλληλα με τους τοπικούς λογαριασμούς.',
