        'field_groups_seen_hint' => 'Κάθε ομάδα χρηστών που έχει στείλει ο πάροχος σε κάποια σύνδεση. Ορισμένοι πάροχοι, όπως η Microsoft, στέλνουν κωδικούς αντί για ονόματα — δώστε σε καθεμία ένα όνομα εδώ και οι αναπτυσσόμενες λίστες παρακάτω θα δείχνουν το όνομα. Βρείτε τον κωδικό δίπλα στο όνομα της ομάδας στον πάροχό σας (στο Microsoft Entra: Groups, η ομάδα, Object ID).',
