        'carddav_write_heading' => 'Αποστολή αλλαγών πίσω',
        'carddav_write_hint' => 'Κανονικά το FreeITSM μόνο διαβάζει αυτό το βιβλίο διευθύνσεων. Ενεργοποιήστε το και μια αλλαγή που κάνει ένας τεχνικός στον τίτλο θέσης, το τμήμα, το γραφείο, το τηλέφωνο ή το κινητό μιας επαφής γράφεται και στην κάρτα της. Ο κωδικός υπαλλήλου και ο προϊστάμενος παραμένουν στο FreeITSM, επειδή η κάρτα επαφής δεν έχει πού να τα φυλάξει.',
        'carddav_write_back' => 'Εγγραφή των αλλαγών που γίνονται στο FreeITSM πίσω στο βιβλίο διευθύνσεων',
        'carddav_allow_create' => 'Να επιτρέπεται στους τεχνικούς να προσθέτουν άτομα σε αυτό το βιβλίο διευθύνσεων',
        'carddav_allow_create_hint' => 'Απενεργοποιημένο από προεπιλογή. Όταν είναι ενεργό, ένα άτομο που δεν υπάρχει σε κανένα βιβλίο διευθύνσεων παίρνει ένα κουμπί Προσθήκη στο βιβλίο διευθύνσεων στα Αιτήματα και στα Πάγια, που δημιουργεί την κάρτα του εδώ και το συσχετίζει. Πριν γραφτεί οτιδήποτε, το FreeITSM ελέγχει ότι κανείς στο βιβλίο δεν έχει ήδη τη διεύθυνση email του και, μετά, ελέγχει ότι η νέα κάρτα είναι τέτοια που την εισάγει αυτή η πηγή — προσθέτοντας την ετικέτα ή την ομάδα χρηστών βάσει της οποίας εισάγει — και την αφαιρεί ξανά αν δεν είναι.',
        'carddav_write_warning' => 'Αλλάζουν μόνο τα στοιχεία που αναφέρονται παραπάνω και μόνο στην επαφή που επεξεργάζεστε. Όλα τα υπόλοιπα στην κάρτα — φωτογραφία, σημειώσεις, γενέθλια, πλήρης διεύθυνση, ομάδες χρηστών — μένουν ακριβώς όπως είναι. Αν κάποιος έχει αλλάξει το ίδιο στοιχείο στο βιβλίο διευθύνσεων από την τελευταία εισαγωγή του FreeITSM, η αλλαγή απορρίπτεται αντί να αντικαταστήσει τη δική του.',
        'carddav_write_check' => 'Έλεγχος δικαιώματος',
