    'webhooks' => [
        'browser_title' => 'Webhooks',
        'title' => 'Webhooks',
        'subtitle' => 'Τα εξερχόμενα webhooks &mdash; που μπαίνουν στην ουρά από την ενέργεια ροής εργασιών <em>Αποστολή webhook</em> &mdash; παραδίδονται στο παρασκήνιο με αυτόματες επαναπροσπάθειες, ώστε ένα αργό ή νεκρό endpoint να μην καθυστερεί ποτέ ένα αίτημα. Αυτή η σελίδα δείχνει αν έχει ρυθμιστεί η παράδοση, μια επισκόπηση της υγείας των παραδόσεων και το πλήρες αρχείο καταγραφής, όπου μπορείτε να δείτε κάθε αίτηση, την απάντησή της και να επαναλάβετε οποιαδήποτε από αυτές.',
        'pill_running' => 'Η διεργασία παράδοσης λειτουργεί',
