        'pill_down' => 'Η διεργασία παράδοσης έχει σταματήσει',
        'pill_never' => 'Δεν έχει ρυθμιστεί ακόμη',
        'last_ran' => 'Τελευταία εκτέλεση {when}',
        'running_ok' => 'Η διεργασία παρασκηνίου λειτουργεί και παραδίδει την ουρά.',
