        'waiting_many' => '<strong>{n}</strong> webhooks σε αναμονή &mdash; θα σταλούν μέσα σε ένα λεπτό.',
        'nothing_waiting' => 'Προς το παρόν δεν περιμένει τίποτα.',
        'never_explain' => '<strong>Τα webhooks δεν θα σταλούν</strong> μέχρι να προγραμματιστεί η εκτέλεση της διεργασίας παράδοσης παρασκηνίου.',
        'down_explain' => '<strong>Τα webhooks δεν στέλνονται πλέον</strong> &mdash; η διεργασία εκτελέστηκε τελευταία φορά {when} και φαίνεται ότι έχει σταματήσει.',
        'stale_explain' => 'Η διεργασία λειτουργεί αλλά καθυστερεί σε σχέση με το πρόγραμμα (τελευταία εκτέλεση {when}). Θα έπρεπε να εκτελείται κάθε λεπτό.',
        'queued_one' => '<strong>1</strong> webhook βρίσκεται στην ουρά και περιμένει.',
        'queued_many' => '<strong>{n}</strong> webhooks βρίσκονται στην ουρά και περιμένουν.',
        'step1' => '<strong>Προγραμματίστε την εκτέλεση της διεργασίας παράδοσης κάθε λεπτό.</strong> Στον διακομιστή, εκτελέστε αυτή την εντολή από μια προγραμματισμένη εργασία (Windows Task Scheduler) ή από cron (Linux):',
        'step1_http' => 'Δεν μπορείτε να εκτελέσετε PHP από το κέλυφος; Καλέστε την μέσω HTTP (π.χ. από μια φιλοξενούμενη υπηρεσία cron):',
        'step2' => '<strong>Προσθέστε την ενέργεια <em>Αποστολή webhook</em> σε μια ροή εργασιών</strong> ώστε να αρχίσουν να γεμίζουν την ουρά τα συμβάντα &mdash; στις <a href="{url}">Ροές εργασιών</a>.',
        'step3' => '<strong>Παρακολουθήστε αυτή τη σελίδα.</strong> Μόλις λειτουργήσει η διεργασία, η παραπάνω κατάσταση γίνεται πράσινη και οι παραδόσεις εμφανίζονται παρακάτω. Αναλυτικές οδηγίες ρύθμισης (Windows &amp; Linux, επαλήθευση υπογραφής) υπάρχουν στο <a href="https://github.com/edmozley/freeitsm/wiki/Workflows" target="_blank" rel="noopener">wiki των Ροών εργασιών</a>.',
        'fact_worker' => 'Σενάριο διεργασίας',
        'fact_retry' => 'Πρόγραμμα επαναπροσπαθειών',
