        'fact_queued' => 'Στην ουρά τώρα',
        'days' => '{n} ημέρες',
        'del_title' => 'Παράδοση',
        'del_desc' => 'Πόσο επίμονα προσπαθεί το FreeITSM να περάσει κάθε webhook.',
        'opt_default' => '{label} (προεπιλογή)',
        'del_attempts_label' => 'Προσπάθειες πριν την παραίτηση',
        'del_attempts_one' => '1 προσπάθεια (χωρίς επαναπροσπάθειες)',
        'del_attempts_opt' => '{n} προσπάθειες',
        'del_attempts_help' => 'Μια αποτυχημένη προσπάθεια επαναλαμβάνεται μετά από 1 λεπτό, έπειτα μετά από 5 λεπτά, 15 λεπτά, 1 ώρα και 6 ώρες, και στη συνέχεια κάθε 6 ώρες. Μετά την τελευταία προσπάθεια η παράδοση επισημαίνεται ως <strong>Νεκρή</strong> και περιμένει την <em>Επανάληψη</em>. Μια αλλαγή ισχύει για τα webhooks που μπαίνουν στην ουρά από τώρα και στο εξής - όσα βρίσκονται ήδη στην ουρά κρατούν τον αριθμό με τον οποίο ξεκίνησαν.',
        'del_timeout_label' => 'Αναμονή απάντησης από το endpoint',
        'del_timeout_opt' => '{n} δευτερόλεπτα',
        'del_timeout_help' => 'Πόση ώρα περιμένει κάθε προσπάθεια πριν θεωρηθεί αποτυχημένη. Αυξήστε την μόνο για ένα endpoint που είναι γνωστό ότι είναι αργό: η διεργασία στέλνει ένα webhook τη φορά, οπότε μια μεγάλη αναμονή καθυστερεί την υπόλοιπη ουρά. Η <em>Αποστολή δοκιμής</em> στον επεξεργαστή ροών εργασιών περιμένει το πολύ 25 δευτερόλεπτα.',
        'del_int_label' => 'Αν μια αποστολή διακοπεί στη μέση',
        'del_int_retry' => 'Δοκιμή ξανά - το endpoint μπορεί να το λάβει δύο φορές',
        'del_int_stop' => 'Διακοπή και αναμονή για Επανάληψη',
        'del_int_help' => 'Αν η διεργασία σταματήσει στη μέση μιας αποστολής - επανεκκίνηση του διακομιστή ή τερματισμός της προγραμματισμένης εργασίας - κανείς δεν γνωρίζει αν το endpoint το έλαβε. Μετά από 10 λεπτά το FreeITSM το ρυθμίζει: το <strong>Δοκιμή ξανά</strong> το μετράει ως αποτυχημένη προσπάθεια και επαναλαμβάνει σύμφωνα με το παραπάνω πρόγραμμα· το <strong>Διακοπή</strong> το επισημαίνει αμέσως ως Νεκρό, ώστε να ελέγξετε το endpoint και να το επαναλάβετε μόνοι σας. Κάθε αποστολή φέρει μια κεφαλίδα <code>X-FreeITSM-Delivery</code> με τον ίδιο αριθμό σε κάθε προσπάθεια και σε κάθε Επανάληψη, ώστε ένας δέκτης που διαχειρίζεστε εσείς να μπορεί να αγνοήσει μια επανάληψη. Εργαλεία συνομιλίας όπως το Slack και το Teams δεν μπορούν και θα εμφάνιζαν το μήνυμα δύο φορές.',
        'dp_title' => 'Προστασία δεδομένων',
        'dp_desc' => 'Τι κρατά το FreeITSM στον δίσκο για τα webhooks σας και για πόσο διάστημα.',
        'enc_on_title' => 'Οι διευθύνσεις URL και τα μυστικά υπογραφής των webhooks είναι κρυπτογραφημένα κατά την αποθήκευση',
        'enc_on_body' => 'Αποθηκεύονται με AES-256-GCM, στη ροή εργασιών και στην ουρά παράδοσης. Μια διεύθυνση URL webhook είναι από μόνη της διαπιστευτήριο &mdash; όποιος την έχει μπορεί να δημοσιεύσει στο κανάλι σας &mdash; και το μυστικό υπογραφής είναι αυτό που αποδεικνύει ότι ένα μήνυμα προήλθε πράγματι από εσάς.',
        'enc_off_title' => 'Δεν έχει ρυθμιστεί κλειδί κρυπτογράφησης &mdash; οι διευθύνσεις URL και τα μυστικά υπογραφής των webhooks αποθηκεύονται ως απλό κείμενο',
        'enc_off_body' => 'Το FreeITSM τα κρυπτογραφεί όταν υπάρχει αρχείο κλειδιού κρυπτογράφησης, αλλά αυτή η εγκατάσταση δεν έχει κανένα, οπότε αποθηκεύονται ως έχουν αντί να αποτυγχάνουν εντελώς τα webhooks σας. Όποιος μπορεί να διαβάσει τη βάση δεδομένων ή ένα αντίγραφο ασφαλείας της μπορεί να δημοσιεύσει στα κανάλια σας και να πλαστογραφήσει τις υπογραφές σας. Ρυθμίστε το κλειδί κρυπτογράφησης (<code>ENCRYPTION_KEY_PATH</code>) και αποθηκεύστε ξανά κάθε ροή εργασιών webhook για να κρυπτογραφηθούν οι αποθηκευμένες τιμές.',
        'ret_label' => 'Διατήρηση απεσταλμένων δεδομένων για',
