        'ret_30' => '30 ημέρες',
        'ret_forever' => 'Όσο διαρκεί η εγγραφή παράδοσης',
        'ret_help' => 'Το αρχείο καταγραφής παραδόσεων αποθηκεύει ακριβώς τα δεδομένα που στάλθηκαν. Με τη μορφή <strong>Πλήρης εγγραφή</strong> αυτό είναι <strong>ολόκληρο αίτημα</strong> &mdash; θέμα, αιτών, τα πάντα &mdash; αντιγραμμένο εδώ ως απλό κείμενο. Μετά από τόσες ημέρες τα δεδομένα και τα σώματα των απαντήσεων σβήνονται, ενώ η <em>εγγραφή</em> παράδοσης (endpoint, κατάσταση, χρόνος, σφάλματα) διατηρείται για έλεγχο μέχρι να αφαιρέσει ολόκληρη τη γραμμή η παραπάνω διατήρηση του αρχείου καταγραφής ({days} ημέρες).',
        'ret_tradeoff' => '<strong>Συμβιβασμός:</strong> Η <em>Επανάληψη</em> ξαναστέλνει τα αποθηκευμένα δεδομένα, οπότε μια παράδοση της οποίας τα δεδομένα έχουν σβηστεί δεν μπορεί πλέον να επαναληφθεί. Η Επανάληψη χρησιμοποιείται συνήθως μέσα σε λίγες ώρες από μια αποτυχία, όχι μετά από εβδομάδες.',
