        'needs_verify' => 'Εκτελέστε πρώτα Σύστημα → Επαλήθευση βάσης δεδομένων. Μέχρι να ολοκληρωθεί, οι προϊστάμενοι παραμένουν απενεργοποιημένοι ανεξάρτητα από τη ρύθμιση εδώ, γιατί δεν θα ήταν δυνατό να ξεχωρίσουν τα εμπιστευτικά αιτήματα.',
